'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var zmq = require( 'zeromq' );
var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var format = require( '@stdlib/string/format' );
var log = require( './../custom_log.js' );


// VARIABLES //

// NOTE: We are not using the latest zeromq bindings. Mainly for event driven architecture.
// var ZMQ_SOCKETS = {
// 	'pair': zmq.Pair,
// 	'publisher': zmq.Publisher,
// 	'subscriber': zmq.Subscriber,
// 	'request': zmq.Request,
// 	'reply': zmq.Reply,
// 	'dealer': zmq.Dealer,
// 	'router': zmq.Router,
// 	'pull': zmq.Pull,
// 	'push': zmq.Push,
// 	'xpublisher': zmq.XPublisher,
// 	'xsubscriber': zmq.XSubscriber,
// 	'stream': zmq.Stream
// };


// FUNCTIONS //

/**
* Constructs an address.
*
* @private
* @param {string} transport - protocol name
* @param {string} ip - client address
* @param {number} port - client port
* @returns {string} address
*/
function constructAddress( transport, ip, port ) {
	return format( '%s://%s:%d', transport, ip, port );
}


// MAIN //

/**
* Socket constructor.
*
* @private
* @constructor
* @param {string} type - socket type
* @param {string} ip - client address
* @param {number} port - client port
* @param {string} transport - protocol name
* @returns {Socket} socket instance
*/
function Socket( type, ip, port, transport ) {
	if ( !( this instanceof Socket ) ) {
		return new Socket( type, ip, port, transport );
	}

	// Call the parent constructor:
	EventEmitter.call( this );

	// Socket address:
	this._address = constructAddress( transport, ip, port );

	// Initialize socket:
	this._socket = new zmq.Socket( type );

	// Bind to address:
	console.log(this._address);
	this._socket.bindSync( this._address ); // eslint-disable-line node/no-sync

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Socket, EventEmitter );

/**
* Initializes message listener on the zmq socket.
*
* @private
* @name listen
* @memberof Socket.prototype
* @type {Function}
* @returns {void}
*/
setNonEnumerableReadOnly( Socket.prototype, 'listen', function listen() {
	var self = this;
	this._socket.on( 'message', onMessage );

	/**
	* Callback invoked upon receiving a zmq "message" event.
	*
	* @private
	* @param {...Buffer} args - raw message frames
	* @returns {void}
	*/
	function onMessage() {
		// log( 'got a message dam on port: ' + String( self._address ) + ' of length: '+arguments.length );
		var frames = Array.prototype.slice.call( arguments );
		self.emit( 'message', frames );
	}
});

/**
* Sends a message over the zmq socket.
*
* @private
* @name send
* @memberof Socket.prototype
* @type {Function}
* @param {Array<Buffer} message - raw message frames
* @returns {void}
*/
setNonEnumerableReadOnly( Socket.prototype, 'send', function send( message ) {
	// console.error( JSON.stringify( message ) );
	this._socket.send( message );
});

// TODO: add methods for graceful closing.


// EXPORTS //

module.exports = Socket;
